int NAND_Snprintf(char *str, unsigned int size, const char *fmt, ...)
{
	int rtn = 0;
	va_list args;

	va_start(args, fmt);

	rtn = vsnprintf(str, size, fmt, args);

	va_end(args);

	return rtn;
}

int NAND_Sprintf(char *str, const char *fmt, ...)
{
	int rtn = 0;
	va_list args;

	va_start(args, fmt);

	rtn = vsprintf(str, fmt, args);

	va_end(args);

	return rtn;
}

int NAND_Print(const char *fmt, ...)
{
	int rtn = 0;
	va_list args;

	va_start(args, fmt);

	vsyslog(LOG_ERR, fmt, args);

	va_end(args);
	return rtn;
}

int NAND_Print_DBG(const char *fmt, ...)
{
	int rtn = 0;
	va_list args;

	va_start(args, fmt);


	vsyslog(LOG_DEBUG, fmt, args);

	va_end(args);
	return rtn;
}

void NAND_Mdelay(unsigned long ms)
{
	hal_udelay(ms * 1000);
}

